# the waiting blocks (D) + the grown-back spots still checked / kept (V) in the owner's chunks: out of memory without a block write, an R
# journal line per waiting block, then a fresh snapshot (an unreadable-at-start world keeps its files: the R lines still say it)
M(bx, r"""
public static boolean spool(String sp, String s) {
  if (sp == null || sp.length() == 0 || s == null || s.length() == 0) return true;
  try {
    java.nio.file.Path f = new java.io.File(sp).toPath();
    java.nio.file.Files.createDirectories(f.getParent(), new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Files.write(f, s.getBytes("UTF-8"), new java.nio.file.OpenOption[] { java.nio.file.StandardOpenOption.CREATE, java.nio.file.StandardOpenOption.APPEND, java.nio.file.StandardOpenOption.DSYNC });
    return true;
  } catch (Throwable t) { @PKG@.ZCfg.warnOnce("zboxspool", "zone reset: could not write the spool " + sp + ": " + t); return false; }
}""")
# fix round 2 (critic: a crash inside the drop lost the rows): every line is READ first and spooled (sp, a file in SkyyWorldGen's reset
# backup, synced) BEFORE anything is dropped - a crash part way leaves them for SkyyWorldGen's next start; no spool -> nothing dropped
M(bx, r"""
public static String drop(String w, java.util.function.IntBinaryOperator f, String sp) {
  @PKG@.ZRw r = @PKG@.ZRegen.rw(w, false);
  if (r == null) return "";
  java.util.ArrayList ds = new java.util.ArrayList();
  java.util.ArrayList cs = new java.util.ArrayList();
  java.util.ArrayList rs = new java.util.ArrayList();
  StringBuilder all = new StringBuilder();
  java.util.Iterator it = r.dep.values().iterator();
  while (it.hasNext()) {
    @PKG@.ZDep d = (@PKG@.ZDep) it.next();
    if (!owned(f, d.x, d.z)) continue;
    ds.add(new Object[] { d, d.line() });
    all.append(d.line()).append('\n');
  }
  java.util.Iterator ci = r.check.values().iterator();
  while (ci.hasNext()) {
    @PKG@.ZDep v = (@PKG@.ZDep) ci.next();
    if (!owned(f, v.x, v.z)) continue;
    cs.add(v);
    all.append(v.vline()).append('\n');
  }
  java.util.Iterator ri = r.recent.values().iterator();
  while (ri.hasNext()) {
    @PKG@.ZDep v = (@PKG@.ZDep) ri.next();
    if (!owned(f, v.x, v.z)) continue;
    rs.add(v);
    all.append(v.vline()).append('\n');
  }
  java.util.ArrayList tsx = new java.util.ArrayList();   // 0.3.0: felled trees (origin chunk) - each as its shape line + its G line
  java.util.Iterator tti = r.trees.values().iterator();
  while (tti.hasNext()) {
    @PKG@.ZTree t = (@PKG@.ZTree) tti.next();
    if (!owned(f, t.x, t.z)) continue;
    tsx.add(t);
    all.append(t.shape.bline()).append('\n').append(t.line()).append('\n');
  }
  java.util.ArrayList tvx = new java.util.ArrayList();   // 0.3.0: grown-back trees still checked / kept (W lines)
  java.util.Iterator tvi = r.tcheck.values().iterator();
  while (tvi.hasNext()) { @PKG@.ZTree t = (@PKG@.ZTree) tvi.next(); if (owned(f, t.x, t.z)) { tvx.add(t); all.append(t.shape.bline()).append('\n').append(t.wline()).append('\n'); } }
  tvi = r.trecent.values().iterator();
  while (tvi.hasNext()) { @PKG@.ZTree t = (@PKG@.ZTree) tvi.next(); if (owned(f, t.x, t.z) && !r.tcheck.containsKey(Long.valueOf(t.key))) { tvx.add(t); all.append(t.shape.bline()).append('\n').append(t.wline()).append('\n'); } }
  if (!spool(sp, all.toString())) return "#ERROR the regrow rows could not be saved into the reset backup first (" + sp + ") - nothing was dropped\n";
  StringBuilder sb = new StringBuilder();
  int n = 0;
  for (int i = 0; i < ds.size(); i++) {
    Object[] e = (Object[]) ds.get(i);
    if (r.drop((@PKG@.ZDep) e[0])) { sb.append((String) e[1]).append('\n'); n++; }
  }
  for (int i = 0; i < cs.size(); i++) {
    @PKG@.ZDep v = (@PKG@.ZDep) cs.get(i);
    if (r.check.remove(Long.valueOf(v.key), v)) sb.append(v.vline()).append('\n');
  }
  for (int i = 0; i < rs.size(); i++) {
    @PKG@.ZDep v = (@PKG@.ZDep) rs.get(i);
    if (r.recent.remove(Long.valueOf(v.key), v)) sb.append(v.vline()).append('\n');
  }
  for (int i = 0; i < tsx.size(); i++) {
    @PKG@.ZTree t = (@PKG@.ZTree) tsx.get(i);
    if (r.treeDrop(t)) { sb.append(t.shape.bline()).append('\n').append(t.line()).append('\n'); n++; }
  }
  for (int i = 0; i < tvx.size(); i++) {
    @PKG@.ZTree t = (@PKG@.ZTree) tvx.get(i);
    Long tk = Long.valueOf(t.key);
    if (r.tcheck.remove(tk, t) || r.trecent.remove(tk, t)) sb.append(t.shape.bline()).append('\n').append(t.wline()).append('\n');
  }
  r.snapshot(true);
  DROPPED.addAndGet((long) n);
  if (sb.length() > 0) @PKG@.ZCfg.info("zone reset (SkyyWorldGen): " + n + " waiting regrow block(s) in " + w + " forgotten without growing back (the land is regenerated; they are in the reset backup)");
  return sb.toString();
}""")
M(bx, r"""
public static int restore(String w, String text) {
  @PKG@.ZRw r = @PKG@.ZRegen.rw(w, true);
  if (r == null) return 0 - 1;
  if (text == null) return 0;
  String[] ls = text.split("\n");
  int n = 0;
  java.util.HashMap shp = new java.util.HashMap();   // 0.3.0: the shape lines of the trees below
  for (int i = 0; i < ls.length; i++) {
    String l = ls[i].trim();
    if (l.length() == 0 || l.startsWith("#")) continue;
    String[] a = l.split("\\s+");
    if (a[0].equals("S") && a.length == 4) {
      @PKG@.ZShape sh = @PKG@.ZShape.fromOneLine(a[1], a[2], a[3]);
      if (sh != null) { sh.seal(r.shapes); shp.put(a[1], sh); }
      continue;
    }
    if ((a[0].equals("G") || a[0].equals("W")) && a.length == 8) {
      @PKG@.ZTree t = @PKG@.ZTree.parse(a, (@PKG@.ZShape) shp.get(a[6]));
      if (t == null) continue;
      if (a[0].equals("G") ? r.addTree(t) == 0 : r.addCheck(t)) n++;
      continue;
    }
    @PKG@.ZDep d = @PKG@.ZDep.parse(a);
    if (d == null) continue;
    Long k = Long.valueOf(d.key);
    if (a[0].equals("D")) {
      if (r.dep.putIfAbsent(k, d) != null) continue;
      if (!r.append(d.line())) { r.dep.remove(k, d); continue; }
      n++;
    } else if (r.check.putIfAbsent(k, d) == null) n++;
  }
  r.snapshot(true);
  RESTORED.addAndGet((long) n);
  if (n > 0) @PKG@.ZCfg.info("zone reset undo (SkyyWorldGen): " + n + " regrow entr(ies) of " + w + " put back from the reset backup");
  return n;
}""")
M(bx, r"""
public Object apply(Object o) {
  try {
    if (!(o instanceof Object[])) return null;
    Object[] a = (Object[]) o;
    if (a.length < 2 || !(a[0] instanceof String)) return null;
    String w = (String) a[0];
    if (this.mode == 0) {
      if (!(a[1] instanceof java.util.function.IntBinaryOperator)) return null;
      return drop(w, (java.util.function.IntBinaryOperator) a[1], a.length > 2 && a[2] instanceof String ? (String) a[2] : "");
    }
    if (!(a[1] instanceof String)) return null;
    return Integer.valueOf(restore(w, (String) a[1]));
  } catch (Throwable t) {
    @PKG@.ZCfg.warnOnce("zbox" + this.mode, "zone reset bridge (" + (this.mode == 0 ? "dropBox" : "restoreBox") + ") failed: " + t);
    return null;
  }
}""")

