# =====================================================================================================================================
# 0.3.0 ZMig = the one-time update Mig030 (spec 5, PROJECT-RULES 4; the reviewed SkyyCoins CoinMigP7 text step): regen.properties
# regrow.logs / regrow.crops rewritten ONLY while they hold the 0.2.x default 0,none; the zone ores' regrow + type lines appended ONLY when
# absent; the file's own line endings and every other byte kept; a java.util.Properties check that nothing else differs; the kit's
# verified History copies first; one Changes line per key (via migration, Undo); the marker file migrate-0.3.0.done last
# =====================================================================================================================================
mig = mk("ZMig")
for f in ('public static final String WHO = "SkyyZones 0.3.0";', 'public static final String MARK = "migrate-0.3.0.done";',
          'public static final String HEAD = "# SkyyZones 0.3.0: the zone ores (SkyyWorldGen) - added once by the 0.3.0 update (Mig030)";',
          'public static final String[] RK = new String[] { "regrow.logs", "regrow.crops" };',
          'public static final String[] RO = new String[] { "0,none", "0,none" };',
          'public static final String[] RN = new String[] { "60,none", "10,stage1" };',
          "public static final String[] RA = new String[] { %s };" % ", ".join(jl("regrow." + t) for t, _i in ZONE_ORE_TYPES),
          "public static final String[] RAV = new String[] { %s };" % ", ".join(jl("%d,%s" % (dict(REGROW)[t], PLACEHOLDER)) for t, _i in ZONE_ORE_TYPES),
          "public static final String[] TA = new String[] { %s };" % ", ".join(jl("type." + t) for t, _i in ZONE_ORE_TYPES),
          "public static final String[] TAV = new String[] { %s };" % ", ".join(jl(i) for _t, i in ZONE_ORE_TYPES),
          "public static volatile String LAST = \"\";"):
    F(mig, f)
assert dict(REGROW)["logs"] == 60 and dict(REGROW)["crops"] == 10, "Mig030's new values = the new defaults"
M(mig, r"""
public static int idx(String[] a, String k) {
  for (int i = 0; k != null && i < a.length; i++) if (a[i].equals(k)) return i;
  return -1;
}""")
M(mig, r"""
public static String norm(String v) {
  return v == null ? "" : v.replace('|', ',').replaceAll("\\s+", "").toLowerCase();
}""")
# update(text, rewrite keys, their old default, their new value, append keys, their values) -> Object[] { new text, String[] rows (key,
# old or null = added, new)*, String kept (hand-edited lines left as they are) }
M(mig, r"""
public static Object[] update(String text, String[] rk, String[] ro, String[] rn, String[] ak, String[] av) {
  String[] raw = text.split("\n", -1);
  java.util.ArrayList l = new java.util.ArrayList();
  for (int i = 0; i < raw.length; i++) { String s0 = raw[i]; if (s0.endsWith("\r")) s0 = s0.substring(0, s0.length() - 1); l.add(s0); }
  java.util.HashSet have = new java.util.HashSet();
  java.util.ArrayList rows = new java.util.ArrayList();
  StringBuilder kept = new StringBuilder();
  java.util.ArrayList out = new java.util.ArrayList();
  int k = 0;
  while (k < l.size()) {
    String s = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s)) { out.add(raw[k]); k++; continue; }
    int e = @PKG@.CfgFile.end(l, k);
    String key = @PKG@.CfgFile.key(s);
    if (key != null) have.add(key);
    int j = idx(rk, key);
    if (j >= 0) {
      String v = @PKG@.CfgFile.value(l, k).trim();
      if (e == k && norm(v).equals(norm(ro[j]))) {
        String cr1 = raw[k].endsWith("\r") ? "\r" : "";
        out.add(s.substring(0, @PKG@.CfgFile.valStart(s)) + rn[j] + cr1);
        rows.add(key); rows.add(v); rows.add(rn[j]);
        k = e + 1;
        continue;
      }
      if (!norm(v).equals(norm(rn[j]))) kept.append(kept.length() > 0 ? ", " : "").append(key).append('=').append(@PKG@.CfgRows.oneLine(v));
    }
    for (int q = k; q <= e; q++) out.add(raw[q]);
    k = e + 1;
  }
  String cr = text.indexOf("\r\n") >= 0 ? "\r" : "";
  java.util.ArrayList add = new java.util.ArrayList();
  for (int i = 0; i < ak.length; i++) {
    if (have.contains(ak[i])) continue;
    add.add(ak[i] + "=" + av[i] + cr);
    rows.add(ak[i]); rows.add(null); rows.add(av[i]);
  }
  if (!add.isEmpty()) {
    int at = out.size() - 1;
    if (at < 0) { out.add(""); at = 0; }
    if (((String) out.get(at)).length() != 0) { out.set(at, (String) out.get(at) + cr); out.add(""); at = out.size() - 1; }
    out.add(at, HEAD + cr);
    at++;
    for (int i = 0; i < add.size(); i++) { out.add(at, add.get(i)); at++; }
  }
  StringBuilder sb = new StringBuilder(text.length() + 256);
  for (int i = 0; i < out.size(); i++) { if (i > 0) sb.append('\n'); sb.append((String) out.get(i)); }
  return new Object[] { sb.toString(), (String[]) rows.toArray(new String[0]), kept.toString() };
}""")
# only the listed keys differ (rewritten values / appended keys); everything else reads the same
M(mig, r"""
public static boolean sameAfter(byte[] old, byte[] nb, String[] rows) {
  try {
    java.util.Properties a = new java.util.Properties();
    java.util.Properties b = new java.util.Properties();
    a.load(new java.io.ByteArrayInputStream(old));
    b.load(new java.io.ByteArrayInputStream(nb));
    int added = 0;
    for (int i = 0; i + 2 < rows.length; i += 3) {
      if (rows[i + 1] == null) { added++; if (a.getProperty(rows[i]) != null || !rows[i + 2].equals(b.getProperty(rows[i]))) return false; }
    }
    if (b.size() != a.size() + added) return false;
    java.util.Iterator it = a.stringPropertyNames().iterator();
    while (it.hasNext()) {
      String k = (String) it.next();
      String want = a.getProperty(k);
      for (int i = 0; i + 2 < rows.length; i += 3) if (rows[i].equals(k)) want = rows[i + 2];
      String got = b.getProperty(k);
      if (got == null || !got.equals(want)) return false;
    }
    return true;
  } catch (Throwable t) { return false; }
}""")
M(mig, r"""
public static int fileIdx(String name) {
  for (int k = 0; k < @PKG@.CfgRows.FILES.length; k++) if (@PKG@.CfgRows.FILES[k].endsWith("Skyy_SkyyZones/" + name)) return k;
  return -1;
}""")
M(mig, r"""
public static boolean saved(int f, byte[] old) {
  String[] have = @PKG@.CfgHist.list(f);
  for (int i = have.length - 1; i >= 0; i--) {
    try { if (java.util.Arrays.equals(java.nio.file.Files.readAllBytes(@PKG@.CfgHist.bak(f, have[i])), old)) return true; } catch (Throwable x) { }
  }
  return false;
}""")
# the Server Setup -> Changes line of one key (table form: regrow[logs] 0|none -> 60|none, type[lead] (none) -> the ids) - Undo works on it
M(mig, r"""
public static String logLine(String k, String o, String n) {
  boolean rg = k.startsWith("regrow.");
  String key = rg ? "regrow[" + k.substring(7) + "]" : "type[" + k.substring(5) + "]";
  String ov = o == null ? "(none)" : (rg ? o.replace(',', '|') : o);
  String nv = rg ? n.replace(',', '|') : n;
  return @PKG@.CfgLog.now() + "\t" + WHO + "\t-\tmigration\t" + key + "\t" + @PKG@.CfgRows.oneLine(ov) + "\t" + @PKG@.CfgRows.oneLine(nv) + "\tok";
}""")
M(mig, r"""
public static void mark(java.nio.file.Path m, String what) {
  try {
    java.nio.file.Files.createDirectories(m.getParent(), new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Files.write(m, ("SkyyZones 0.3.0 one-time update (Mig030) done " + new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss").format(new java.util.Date()) + ": " + what + "\n").getBytes("UTF-8"), new java.nio.file.OpenOption[0]);
  } catch (Throwable t) { @PKG@.ZCfg.warn("could not write " + m + " (the 0.3.0 update runs again at the next start - it changes nothing twice): " + t); }
}""")
# run(dir): "" = nothing done (marker there, or a failure: WARN, files untouched, the next start tries again); else the summary. A fresh
# folder (neither file yet) only gets the marker - the default files it writes next already carry the 0.3.0 rows
M(mig, r"""
public static synchronized String run(java.nio.file.Path dir) {
  if (dir == null) return "";
  try {
    java.nio.file.Path m = dir.resolve(MARK);
    if (java.nio.file.Files.exists(m, new java.nio.file.LinkOption[0])) return "";
    java.nio.file.Path rf = dir.resolve("regen.properties");
    java.nio.file.Path tf = dir.resolve("types.properties");
    boolean hr = java.nio.file.Files.exists(rf, new java.nio.file.LinkOption[0]);
    boolean ht = java.nio.file.Files.exists(tf, new java.nio.file.LinkOption[0]);
    if (!hr && !ht) { mark(m, "a new folder - the default files carry the 0.3.0 rows"); return ""; }
    byte[] ro = null;
    byte[] to = null;
    byte[] rn = null;
    byte[] tn = null;
    String[] rr = new String[0];
    String[] tr = new String[0];
    String kept = "";
    if (hr) {
      ro = java.nio.file.Files.readAllBytes(rf);
      Object[] ur = update(new String(ro, "ISO-8859-1"), RK, RO, RN, RA, RAV);
      rn = ((String) ur[0]).getBytes("ISO-8859-1");
      rr = (String[]) ur[1];
      kept = (String) ur[2];
    }
    if (ht) {
      to = java.nio.file.Files.readAllBytes(tf);
      Object[] ut = update(new String(to, "ISO-8859-1"), new String[0], new String[0], new String[0], TA, TAV);
      tn = ((String) ut[0]).getBytes("ISO-8859-1");
      tr = (String[]) ut[1];
    }
    if ((rn != null && !sameAfter(ro, rn, rr)) || (tn != null && !sameAfter(to, tn, tr))) {
      @PKG@.ZCfg.warn("the 0.3.0 update (Mig030) would change more than its own lines - regen.properties / types.properties are used as they are (the next start tries again)");
      return "";
    }
    boolean rch = rn != null && !java.util.Arrays.equals(ro, rn);
    boolean tch = tn != null && !java.util.Arrays.equals(to, tn);
    if (rch || tch) {
      int fr = fileIdx("regen.properties");
      int ft = fileIdx("types.properties");
      if (fr < 0 || ft < 0) return "";
      @PKG@.CfgRows.HOME = dir.toAbsolutePath();
      if (@PKG@.CfgRows.LOG == null) @PKG@.CfgRows.LOG = @PKG@.ZCfg.LOG;
      @PKG@.CfgHist.init();
      @PKG@.CfgLog.init();
      String st = @PKG@.CfgHist.stamp();
      if (hr) @PKG@.CfgHist.snapshot(fr, ro, st, WHO, "before the 0.3.0 update (Mig030: whole trees, crops, zone ores)");
      if (ht) @PKG@.CfgHist.snapshot(ft, to, st, WHO, "before the 0.3.0 update (Mig030: zone ore types)");
      if ((hr && !saved(fr, ro)) || (ht && !saved(ft, to))) {
        @PKG@.ZCfg.warn("the 0.3.0 update (Mig030) is NOT done: the old files could not be kept in " + @PKG@.CfgHist.DIR + " (they are used as they are; the next start tries again)");
        return "";
      }
      if (rch) {   // fixer: each file's Changes lines right after ITS write (a failed second write never loses the first file's Undo lines)
        @PKG@.CfgRows.atomicWrite(rf, rn);
        for (int i = 0; i + 2 < rr.length; i += 3) @PKG@.CfgLog.enqueue(logLine(rr[i], rr[i + 1], rr[i + 2]));
        @PKG@.CfgLog.flush();
      }
      if (tch) {
        @PKG@.CfgRows.atomicWrite(tf, tn);
        for (int i = 0; i + 2 < tr.length; i += 3) @PKG@.CfgLog.enqueue(logLine(tr[i], tr[i + 1], tr[i + 2]));
        @PKG@.CfgLog.flush();
      }
    }
    if (kept.length() > 0) @PKG@.ZCfg.info("the 0.3.0 update keeps hand-edited lines as they are: " + kept + " (trees / crops regrow with those values)");
    String msg = "one-time 0.3.0 update (Mig030): " + (rr.length + tr.length) / 3 + " lines changed / added" + (kept.length() > 0 ? ", kept (hand-edited): " + kept : "") + " (old files in config-history; Server Setup -> Changes can undo each line)";
    mark(m, msg);
    LAST = msg;
    @PKG@.ZCfg.info(msg);
    return msg;
  } catch (Throwable t) {
    @PKG@.ZCfg.warn("the 0.3.0 update (Mig030) failed - regen.properties / types.properties are used as they are (the next start tries again): " + t);
    return "";
  }
}""")

